        blockNumber = bound(blockNumber, 1, type(uint256).max);
        warpTime = bound(warpTime, 1, type(uint256).max);
        vm.roll(blockNumber);
        vm.warp(warpTime);

        address sender = makeAddr("sender");
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback failed");

        uint256 finalBalance = address(c).balance;
        if (blockNumber % 15 != 0) {
            assertTrue(finalBalance > 0);
        } else {
            assertTrue(true);
        }
    }
}
